describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow("upToGrams must be a positive integer");
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow("costCents must be a non-negative integer");
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            5.5,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      expect(calc.computeShippingCents([noWeightLine("a", 3)], 5000)).toBe(0);
    });

    it("selects first bracket when weight equals boundary", () => {
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    });

    it("selects first bracket when weight is below boundary", () => {
      expect(calc.computeShippingCents([line("a", 200)], 5000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first boundary", () => {
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(600);
    });

    it("selects second bracket at its boundary", () => {
      expect(calc.computeShippingCents([line("a", 1000)], 5000)).toBe(600);
    });

    it("selects third bracket", () => {
      expect(calc.computeShippingCents([line("a", 1500)], 5000)).toBe(1000);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([line("a", 2500)], 5000)).toBe(1500);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
