      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 5 }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(product("a", 1000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    expect(result.totals.taxCents).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("applies discount before async tax", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      region: "FR",
    });
    cart.add(product("a", 1000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=1000, discount=200, discountedSubtotal=800, tax=0.2*800=160
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(160);
  });

  it("composes discount + async tax + shipping correctly", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(599),
      region: "US",
    });
    cart.add(product("a", 2000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal=2000, discount=200, discountedSubtotal=1800
    // tax = floor(1800 * 0.08) = 144
    // shipping = 599
    // total = 1800 + 144 + 599 = 2543
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(144);
    expect(result.totals.shippingCents).toBe(599);
    expect(result.totals.totalCents).toBe(2543);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("checks inventory for each line, first denial wins", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    cart.add(product("b", 700), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("b");
    }
  });

  it("price refresh happens before inventory check", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const callOrder: string[] = [];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 1000;
      }),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true };
      }),
    };
    await cart.checkout({ priceFetcher: fetcher, inventoryChecker: checker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });
});

describe("InventoryError", () => {
  it("has correct shape", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err).toBeInstanceOf(Error);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});
"}

